export type Outcome = 'succeeded' | 'failed' | 'dead';

const counters: Record<Outcome, number> = { succeeded: 0, failed: 0, dead: 0 };

export function record(outcome: Outcome): void {
  counters[outcome] += 1;
}

export function snapshot(): Record<Outcome, number> {
  return { ...counters };
}

export function resetMetrics(): void {
  counters.succeeded = 0;
  counters.failed = 0;
  counters.dead = 0;
}

export function startMetricsReporter(intervalMs = 60_000): NodeJS.Timeout {
  return setInterval(() => {
    const s = snapshot();
    console.log(`[metrics] succeeded=${s.succeeded} failed=${s.failed} dead=${s.dead}`);
    resetMetrics();
  }, intervalMs).unref();
}

