import { Worker } from 'bullmq';
import IORedis from 'ioredis';
import { logger } from '@tallyhook/shared';
import { processDelivery, REQUEST_TIMEOUT_MS } from './deliver';
import { startMetricsReporter } from './metrics';

const connection = new IORedis(process.env.REDIS_URL ?? 'redis://localhost:6379', {
  maxRetriesPerRequest: null,
});

const worker = new Worker<{ deliveryId: string }>(
  'deliveries',
  async (job) => processDelivery(job.data.deliveryId),
  { connection, concurrency: Number(process.env.WORKER_CONCURRENCY ?? 10) },
);

logger.info({ deliveryTimeoutMs: REQUEST_TIMEOUT_MS }, 'worker started');

worker.on('failed', (job, err) => {
  logger.error({ jobId: job?.id, err }, 'delivery job failed');
});

