import { prisma, logger, backoffDelay, shouldRetry } from '@tallyhook/shared';
import { signPayload, signPayloadV2 } from './signature';
import { isQuietHours, DEFAULT_QUIET_WINDOW } from './quietHours';
import { record } from './metrics';

const DEFAULT_TIMEOUT_MS = 10_000;

export function resolveTimeoutMs(raw: string | undefined): number {
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : DEFAULT_TIMEOUT_MS;
}

export const REQUEST_TIMEOUT_MS = resolveTimeoutMs(process.env.DELIVERY_TIMEOUT_MS);

export async function postWebhook(url: string, body: string, signature: string): Promise<Response> {
  return fetch(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-tallyhook-signature': signature,
    },
    body,
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
}

export async function processDelivery(deliveryId: string): Promise<void> {
  const delivery = await prisma.delivery.findUniqueOrThrow({
    where: { id: deliveryId },
    include: { endpoint: true },
  });
  const { endpoint } = delivery;
  if (endpoint.disabledAt) {
    return;
  }
  if (isQuietHours(DEFAULT_QUIET_WINDOW)) {
    // hold until the window closes; the scheduler picks it up again
    return;
  }

  const body = JSON.stringify(delivery.payload);
  const signature =
    endpoint.signingVersion === 2
      ? signPayloadV2(endpoint.secret, body, Math.floor(Date.now() / 1000))
      : signPayload(endpoint.secret, body);
  const attempt = delivery.attempts + 1;

  try {
    const res = await postWebhook(endpoint.url, body, signature);
    if (!res.ok) {
      throw new Error(`endpoint responded ${res.status}`);
    }
    await prisma.delivery.update({
      where: { id: delivery.id },
      data: { status: 'SUCCEEDED', attempts: attempt, lastError: null },
    });
    record('succeeded');
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const dead = !shouldRetry(attempt, endpoint.maxRetries);
    await recordFailure(delivery.id, attempt, message, dead);
    if (dead) {
      logger.warn({ deliveryId, endpointId: endpoint.id }, 'delivery dead-lettered');
    }
  }
}

async function recordFailure(id: string, attempt: number, message: string, dead: boolean) {
  await prisma.delivery.update({
    where: { id },
    data: {
      status: dead ? 'DEAD' : 'FAILED',
      attempts: attempt,
      lastError: message,
      nextAttemptAt: dead ? undefined : new Date(Date.now() + backoffDelay(attempt)),
    },
  });
  record(dead ? 'dead' : 'failed');
}
